// Synthetic pixel fixtures. CRC uses a separate bitwise implementation;
// encoded filter vectors in core.test.mjs are literal, not generated by the codec.
import { deflateSync, inflateSync } from "node:zlib";
import assert from "node:assert/strict";

export const PNG_SIGNATURE = Buffer.from("89504e470d0a1a0a", "hex");

export function referenceCrc(bytes) {
  let value = 0xffffffff;
  for (const byte of bytes) {
    value ^= byte;
    for (let bit = 0; bit < 8; bit += 1) {
      value = (value >>> 1) ^ (value & 1 ? 0xedb88320 : 0);
    }
  }
  return (value ^ 0xffffffff) >>> 0;
}

export function chunk(type, data = Buffer.alloc(0)) {
  const out = Buffer.alloc(data.length + 12);
  out.writeUInt32BE(data.length, 0);
  out.write(type, 4, 4, "ascii");
  data.copy(out, 8);
  out.writeUInt32BE(referenceCrc(out.subarray(4, out.length - 4)), out.length - 4);
  return out;
}

export function png({
  width = 1, height = 1, colorType = 6, bitDepth = 8,
  interlace = 0, compression = 0, filter = 0,
  scanlines = Buffer.from("0001020304", "hex"),
  compressed = deflateSync(scanlines), before = [], after = [], dataParts = [compressed],
} = {}) {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = bitDepth;
  ihdr[9] = colorType;
  ihdr[10] = compression;
  ihdr[11] = filter;
  ihdr[12] = interlace;
  return Buffer.concat([
    PNG_SIGNATURE, chunk("IHDR", ihdr), ...before,
    ...dataParts.map((data) => chunk("IDAT", data)), ...after, chunk("IEND"),
  ]);
}

export function readNormalized(bytes) {
  assert.deepEqual(bytes.subarray(0, 8), PNG_SIGNATURE);
  const chunks = [];
  let at = 8;
  while (at < bytes.length) {
    const size = bytes.readUInt32BE(at);
    const type = bytes.toString("ascii", at + 4, at + 8);
    const data = bytes.subarray(at + 8, at + 8 + size);
    assert.equal(referenceCrc(bytes.subarray(at + 4, at + size + 8)), bytes.readUInt32BE(at + size + 8));
    chunks.push({ type, data });
    at += size + 12;
  }
  assert.equal(at, bytes.length);
  assert.deepEqual(chunks.map((c) => c.type), ["IHDR", "IDAT", "IEND"]);
  const ihdr = chunks[0].data;
  assert.deepEqual([...ihdr.subarray(8)], [8, 6, 0, 0, 0]);
  const width = ihdr.readUInt32BE(0);
  const height = ihdr.readUInt32BE(4);
  const raw = inflateSync(chunks[1].data);
  assert.equal(raw.length, (width * 4 + 1) * height);
  const rows = [];
  for (let row = 0; row < height; row += 1) {
    const start = row * (width * 4 + 1);
    assert.equal(raw[start], 0);
    rows.push(raw.subarray(start + 1, start + 1 + width * 4));
  }
  return { width, height, rgba: Buffer.concat(rows) };
}
